      ]
    },
    {
      "ambiguity_id": "uncertainty_convention",
      "statement": "The uncertainty convention for reported plus/minus values (e.g., T = 1.8 +/- 0.1 mK, R_bg = 0.10 +/- 0.03 s^-1) is not specified; it is not stated whether these are standard errors, confidence intervals, or fit uncertainties.",
      "claim_ids": ["kl_rate_identical_ions"],
      "mechanism_ids": ["kramers_langer_rate"],
      "control_names": [],
